#include <pybind11/complex.h>
#include <pybind11/pybind11.h>
#include <pybind11/stl.h>

namespace py = pybind11;

#include <bluetooth/pcapng_writer.h>
// pydoc.h is automatically generated in the build directory
#include <pcapng_writer_pydoc.h>

void bind_pcapng_writer(py::module& m)
{

    using pcapng_writer = ::gr::bluetooth::pcapng_writer;


    py::class_<pcapng_writer, std::shared_ptr<pcapng_writer>>(m, "pcapng_writer", D(pcapng_writer))

        .def(py::init(&pcapng_writer::make),
             py::arg("filename"),
             D(pcapng_writer, make))


        
        .def("init",&pcapng_writer::init,       
            D(pcapng_writer,init)
        )


        
        .def("is_enabled",&pcapng_writer::is_enabled,       
            D(pcapng_writer,is_enabled)
        )


        
        .def("write_bredr_packet",&pcapng_writer::write_bredr_packet,       
            py::arg("pkt"),
            py::arg("pn"),
            py::arg("timestamp_ns"),
            py::arg("signal_power"),
            py::arg("noise_power"),
            D(pcapng_writer,write_bredr_packet)
        )


        
        .def("write_le_packet",&pcapng_writer::write_le_packet,       
            py::arg("pkt"),
            py::arg("timestamp_ns"),
            py::arg("signal_power"),
            py::arg("noise_power"),
            D(pcapng_writer,write_le_packet)
        )


        
        .def("close",&pcapng_writer::close,       
            D(pcapng_writer,close)
        )

        ;
}
